package com.witchersbestiary.test;
import net.fabricmc.api.ModInitializer;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;import java.nio.file.*;import java.util.*;import com.google.gson.*;import com.witchersbestiary.fist.*;import net.minecraft.util.math.BlockPos;
public final class Stage21JNetworkServer implements ModInitializer {
 private int phase,ticks;private final Path dir=Path.of(System.getProperty("witchersbestiary.stage20eOutput"));private final long[] sent=new long[2];
 private void command(int i,String action)throws Exception{sent[i]=System.currentTimeMillis()+i;Files.writeString(dir.resolve((i==0?"WBOne":"WBTwo")+".command.json"),new Gson().toJson(Map.of("nonce",sent[i],"action",action)));}
 private boolean ack(int i)throws Exception{var f=dir.resolve((i==0?"WBOne":"WBTwo")+".reply.json");return Files.exists(f)&&JsonParser.parseString(Files.readString(f)).getAsJsonObject().get("nonce").getAsLong()==sent[i];}
 public void onInitialize(){if(Files.exists(dir.resolve("tournament-resume.json")))phase=100;ServerTickEvents.END_SERVER_TICK.register(s->{try{if(phase==999)return;if(++ticks>4000)throw new IllegalStateException("Tournament native timeout "+phase);var a=s.getPlayerManager().getPlayer("WBOne");var b=s.getPlayerManager().getPlayer("WBTwo");if(a==null||b==null)return;var ps=List.of(a,b);var w=s.getOverworld();
 if(Boolean.getBoolean("witchersbestiary.stage21jRestart")){
  if(phase==0){for(int i=0;i<2;i++){var p=ps.get(i);var progress=TournamentProgress.get(s);progress.abandon(p.getUuid());if(!progress.enter(p.getUuid(),TournamentProgress.Category.VILLAGE)||!progress.begin(p.getUuid())||!progress.finish(p.getUuid(),true,w.getTime(),FistRewards.get(s)))throw new IllegalStateException("Restart fixture preparation");command(i,"wait");}Files.writeString(dir.resolve("tournament-resume.json"),"{}");Files.writeString(dir.resolve("resume.json"),"{}");s.save(false,true,true);s.stop(false);phase=999;return;}
  if(phase==100){for(int i=0;i<2;i++){var p=ps.get(i);var entry=TournamentProgress.get(s).entry(p.getUuid());if(entry.active!=TournamentProgress.Category.VILLAGE||entry.round!=1||entry.fighting||FistFights.active(p)!=null)throw new IllegalStateException("Round recovery failed");var organizer=FistRegistry.NOVICE.create(w);organizer.refreshPositionAndAngles(p.getX()+2,p.getY(),p.getZ(),0,0);w.spawnEntity(organizer);Tournaments.open(p,organizer);command(i,"tournamentAbandon");}phase=101;return;}
  if(phase==101){if(!ack(0)||!ack(1))return;for(var p:ps)if(TournamentProgress.get(s).entry(p.getUuid()).active!=null)throw new IllegalStateException("Recovered cancellation failed");Files.writeString(dir.resolve("complete.json"),"{\"native_between_round_restart_both_players\":true}");for(int i=0;i<2;i++)command(i,"stop");phase=999;return;}
 }
 if(phase==0){for(int i=0;i<2;i++){var p=ps.get(i);p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);p.getInventory().clear();var center=new BlockPos(i*96,120,0);for(int x=-36;x<=36;x++)for(int z=-36;z<=36;z++){var at=center.add(x,0,z);w.setBlockState(at.down(),net.minecraft.block.Blocks.GRASS_BLOCK.getDefaultState());for(int y=0;y<4;y++)w.setBlockState(at.up(y),net.minecraft.block.Blocks.AIR.getDefaultState());}p.teleport(w,center.getX()+1,120,0,0,0);var n=FistRegistry.NOVICE.create(w);n.refreshPositionAndAngles(center.getX(),120,0,0,0);w.spawnEntity(n);Tournaments.open(p,n);command(i,"tournamentEnter");}phase=1;return;}
 if(!ack(0)||!ack(1))return;
 if(phase==1){for(var p:ps)if(TournamentProgress.get(s).entry(p.getUuid()).active!=TournamentProgress.Category.VILLAGE)throw new IllegalStateException("Native registration failed");for(int i=0;i<2;i++)command(i,"tournamentContinue");phase=2;return;}
 if(phase==2){for(var p:ps)if(FistFights.active(p)==null)throw new IllegalStateException("Native bout absent");if(FistFights.active(a).npc()==FistFights.active(b).npc())throw new IllegalStateException("Shared opponent");for(int i=0;i<2;i++)command(i,"tournamentAbandon");phase=3;return;}
 if(phase==3){for(var p:ps)if(FistFights.active(p)!=null||TournamentProgress.get(s).entry(p.getUuid()).active!=null)throw new IllegalStateException("Native abandonment failed");Files.writeString(dir.resolve("complete.json"),"{\"native_two_client_gui_registration_bout_and_abandon\":true}");for(int i=0;i<2;i++)command(i,"stop");phase=999;}
 }catch(Throwable e){try{Files.writeString(dir.resolve("server-failure.json"),e.toString());}catch(Exception ignored){}phase=999;s.stop(false);}});}
}
